import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

// Parses a spoken play for the live GitHub Pages site, which cannot hold an AI
// key itself. It uses the same prompt as server/prompt.js: the block between
// the markers below is generated by `npm run sync:prompt` in server/, and a
// server test fails if it falls behind.
//
// Provider: set the GROQ_API_KEY secret to use Groq's free tier (fastest).
// Without it the Lovable AI gateway is used. PARSE_MODEL overrides the model.

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version',
};

// BEGIN STATIC_PROMPT - generated by `npm run sync:prompt` in server/, do not edit by hand
const STATIC_PROMPT = "Turn a baseball scorekeeper's spoken words into one scored play. Reply with one JSON object only.\n\nAlways include action, description, runners, rbi, outs_recorded, fielders_involved, confidence. Add other keys only when the words tell you; never write null.\naction: single | double | triple | home run | strikeout | walk | fly out | ground out | hit by pitch | error | fielder's choice | stolen base | wild pitch | passed ball | balk | sacrifice fly\ndescription: under 12 words\nbatter, pitcher: names\nrunners: [{\"from\",\"to\",\"runner\"}] everyone who moved or was put out, batter included as from \"home\". Bases: home, 1st, 2nd, 3rd; to can be \"out\"\nfielders_involved: position numbers as strings\nhit_type: ground ball | line drive | fly ball | pop up | bunt. hit_location: e.g. shortstop, left-center gap. hit_hardness: soft | medium | hard\npitch_type, pitch_location, count: only if said\nconfidence: high | medium | low\nalternatives: only when the words fit more than one action just as well (\"reached when the shortstop booted it\": error or single), the other actions; the scorer is asked to pick\n\nRULES\n- Only runners listed in STATE are on base. Never move a runner off an empty base; if the words seem to, confidence low.\n- Forced runners advance; unmentioned runners stay. A home run scores everyone on base.\n- outs_recorded = runners sent \"out\". rbi = runners reaching home, none on an error, wild pitch, passed ball, balk, steal or double play.\n- Mangled words may be names (\"show hey\" = Shohei); use the intended name.\n- Unsure: best guess, confidence low.\n\nSHORTHAND\nPositions (fielders_involved): 1=pitcher, 2=catcher, 3=first baseman, 4=second baseman, 5=third baseman, 6=shortstop, 7=left fielder, 8=center fielder, 9=right fielder\n\"6-4-3\" = throw order. E5 = error by 5. F8/L7/P4/G6 = fly/line/pop/ground out to that fielder. U3 = unassisted.\nwalk: BB, ball four, free pass. hit by pitch: HBP, plunked, drilled. strikeout: K, punched out; looking: backwards K, rung up\nhome run: HR, homer, dinger, jack, bomb, goes yard; solo shot = nobody on; grand slam = bases loaded, 4 rbi\nSF = sacrifice fly. sac bunt = ground out, hit_type bunt. FC, SB, WP, PB, BK = fielder's choice, stolen base, wild pitch, passed ball, balk. 1B/2B/3B as a play = single/double/triple\ndouble play (DP, turned two, twin killing) = 2 outs, action ground out, or fly out if caught in the air\nline drive: liner, frozen rope, laser. fly ball: can of corn, blooper, Texas Leaguer. ground ball: chopper, dribbler, nubber, roller, worm burner\n\nEXAMPLES\n\"Soto doubles down the right field line, Lindor scores from first\" -> {\"action\":\"double\",\"description\":\"Soto doubles down the right field line, Lindor scores\",\"batter\":\"Soto\",\"runners\":[{\"from\":\"1st\",\"to\":\"home\",\"runner\":\"Lindor\"},{\"from\":\"home\",\"to\":\"2nd\",\"runner\":\"Soto\"}],\"rbi\":1,\"outs_recorded\":0,\"fielders_involved\":[\"9\"],\"hit_location\":\"right field line\",\"hit_type\":\"line drive\"}\n\"sac fly to right, runner tags from third\" -> {\"action\":\"sacrifice fly\",\"description\":\"Fly ball to right field, runner tags from third and scores\",\"runners\":[{\"from\":\"3rd\",\"to\":\"home\"},{\"from\":\"home\",\"to\":\"out\"}],\"rbi\":1,\"outs_recorded\":1,\"fielders_involved\":[\"9\"],\"hit_location\":\"right field\",\"hit_type\":\"fly ball\"}\n\"Ohtani steals second\" -> {\"action\":\"stolen base\",\"description\":\"Ohtani steals second\",\"runners\":[{\"from\":\"1st\",\"to\":\"2nd\",\"runner\":\"Ohtani\"}],\"rbi\":0,\"outs_recorded\":0,\"fielders_involved\":[\"2\",\"6\"]}\n\"Judge got rung up on a slider\" -> {\"action\":\"strikeout\",\"description\":\"Judge caught looking on a slider\",\"batter\":\"Judge\",\"runners\":[{\"from\":\"home\",\"to\":\"out\",\"runner\":\"Judge\"}],\"rbi\":0,\"outs_recorded\":1,\"fielders_involved\":[\"1\",\"2\"],\"pitch_type\":\"slider\"}";
// END STATIC_PROMPT

interface GameState {
  inning?: number;
  half?: string;
  outs?: number;
  score?: { away?: number; home?: number };
  runners?: { first?: string | null; second?: string | null; third?: string | null };
}

// mirrors describeState in server/prompt.js
function describeState(gameState?: GameState | null): string {
  if (!gameState) return "STATE: start of game, top 1, 0 outs, bases empty";
  const r = gameState.runners || {};
  const base = (name?: string | null) => name || "empty";
  return `STATE: ${gameState.half || "top"} ${gameState.inning || 1}, ${gameState.outs || 0} outs, away ${gameState.score?.away || 0} home ${gameState.score?.home || 0}, 1st: ${base(r.first)}, 2nd: ${base(r.second)}, 3rd: ${base(r.third)}`;
}

interface Context {
  battingTeam?: string;
  fieldingTeam?: string;
  batter?: string;
  pitcher?: string;
  players: string[];
}

const MAX_CONTEXT_PLAYERS = 25;
const MAX_NAME_LENGTH = 60;

function cleanName(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const name = value.replace(/\s+/g, " ").trim();
  return name && name.length <= MAX_NAME_LENGTH ? name : undefined;
}

// mirrors parseContext in server/app.js: anything malformed is dropped rather
// than rejected, since context only helps and a play parses without it
function parseContext(raw: unknown): Context | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const input = raw as Record<string, unknown>;
  const seen = new Set<string>();
  const players: string[] = [];
  for (const value of Array.isArray(input.players) ? input.players : []) {
    const name = cleanName(value);
    if (!name || seen.has(name.toLowerCase())) continue;
    seen.add(name.toLowerCase());
    players.push(name);
    if (players.length === MAX_CONTEXT_PLAYERS) break;
  }
  return {
    battingTeam: cleanName(input.battingTeam),
    fieldingTeam: cleanName(input.fieldingTeam),
    pitcher: cleanName(input.pitcher),
    batter: cleanName(input.batter),
    players,
  };
}

// mirrors describeContext in server/prompt.js
function describeContext(context: Context | null): string {
  if (!context) return "";
  const lines: string[] = [];
  const teams: string[] = [];
  if (context.battingTeam) teams.push(`${context.battingTeam} batting`);
  if (context.fieldingTeam) teams.push(`${context.fieldingTeam} fielding`);
  if (teams.length) lines.push(`GAME: ${teams.join(", ")}`);
  if (context.batter) lines.push(`AT BAT: ${context.batter} (the batter unless the words name another)`);
  if (context.pitcher) lines.push(`PITCHING: ${context.pitcher}`);
  if (context.players.length) lines.push(`PLAYERS SO FAR (use these spellings): ${context.players.join(", ")}`);
  return lines.join("\n");
}

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  const started = Date.now();
  try {
    const { transcript, gameState, context } = await req.json();
    // who is batting, pitching and on the card, the same as the local server gets
    const extra = describeContext(parseContext(context));
    if (!transcript) return json({ error: "transcript is required" }, 400);

    const groqKey = Deno.env.get("GROQ_API_KEY");
    const gatewayKey = Deno.env.get("LOVABLE_API_KEY");
    // Groq shut llama-3.3-70b-versatile down on 2026-08-16; gpt-oss-120b is
    // its listed replacement. Groq retires models often, so PARSE_MODEL can
    // swap one in without a code change
    const provider = groqKey
      ? { url: "https://api.groq.com/openai/v1/chat/completions", key: groqKey, model: "openai/gpt-oss-120b" }
      : { url: "https://ai.gateway.lovable.dev/v1/chat/completions", key: gatewayKey, model: "google/gemini-2.5-flash-lite" };
    if (!provider.key) throw new Error("AI key is not configured");
    const model = Deno.env.get("PARSE_MODEL") || provider.model;
    // reasoning models think before answering, and that thinking counts
    // against max_tokens: keep it brief and leave room for the play itself
    const reasoning = /gpt-oss|qwen3/i.test(model);

    const response = await fetch(provider.url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${provider.key}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model,
        messages: [
          { role: "system", content: `${STATIC_PROMPT}\n\n${describeState(gameState)}${extra ? `\n${extra}` : ""}` },
          { role: "user", content: transcript },
        ],
        max_tokens: reasoning ? 1500 : 350,
        temperature: 0,
        response_format: { type: "json_object" },
        ...(reasoning ? { reasoning_effort: "low" } : {}),
      }),
      signal: AbortSignal.timeout(8000),
    });

    if (!response.ok) {
      if (response.status === 429) return json({ error: "Rate limited. Please try again shortly." }, 429);
      if (response.status === 402) return json({ error: "AI credits exhausted." }, 402);
      console.error("AI error:", response.status, await response.text());
      // the provider's status, so a retired model (400/404) or a bad key (401)
      // can be told apart without opening the function logs
      return json({ error: `AI processing failed (${model} answered ${response.status})` }, 500);
    }

    const data = await response.json();
    const content = data.choices?.[0]?.message?.content;
    if (!content) {
      console.error("No content in response:", JSON.stringify(data));
      return json({ error: "No content returned from AI" }, 500);
    }

    // JSON mode should make this a bare object, but tolerate fences and chatter
    const cleaned = content
      .replace(/```json\n?/g, "")
      .replace(/```\n?/g, "")
      .replace(/^[\s\S]*?({[\s\S]*})[\s\S]*$/, "$1")
      .trim();

    try {
      const play = JSON.parse(cleaned);
      const totalMs = Date.now() - started;
      console.log(`parsed in ${totalMs}ms with ${model}: "${transcript}"`);
      return json({ play, timing: { model, total_ms: totalMs } });
    } catch (parseErr) {
      console.error("JSON parse error:", parseErr, "Raw content:", content);
      return json({ error: "Could not parse AI response as JSON" }, 500);
    }
  } catch (e) {
    if (e instanceof Error && e.name === "TimeoutError") {
      return json({ error: "The AI took too long to answer. Try again." }, 504);
    }
    console.error("parse-play error:", e);
    return json({ error: e instanceof Error ? e.message : "Unknown error" }, 500);
  }
});
